public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    for (int len = strings.stream().mapToInt(String::length).max().orElse(0); len >= 1; len--) {
        for (String s : strings) {
            for (int i = 0; i <= s.length() - len; i++) {
                String sub = s.substring(i, i + len);
                String inv = new StringBuilder(sub).reverse().toString();
                for (String other : strings) {
                    if (other.contains(sub) || other.contains(inv)) {
                        return len;
                    }
                }
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    Set<String> substrings = new HashSet<>();
    Set<String> inverseSubstrings = new HashSet<>();
    int maxLength = 0;
    for (String s : strings) {
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String sub = s.substring(i, j);
                String inverse = new StringBuilder(sub).reverse().toString();
                if (sub.length() > maxLength) {
                    maxLength = sub.length();
                }
                substrings.add(sub);
                inverseSubstrings.add(inverse);
            }
        }
    }
    List<String> maxSubstrings = new ArrayList<>();
    for (String sub : substrings) {
        if (sub.length() == maxLength) {
            maxSubstrings.add(sub);
        }
    }
    for (String sub : maxSubstrings) {
        if (inverseSubstrings.contains(sub)) {
            return sub.length();
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    Set<String> substrings = new HashSet<>();
    int maxLength = 0;
    for (String s : strings) {
        if (s == null) continue;
        int n = s.length();
        for (int len = n; len >= 1; len--) {
            for (int start = 0; start <= n - len; start++) {
                String sub = s.substring(start, start + len);
                substrings.add(sub);
                StringBuilder sb = new StringBuilder(sub);
                for (int i = 0; i < sb.length(); i++) {
                    char c = sb.charAt(i);
                    if (c >= 'A' && c <= 'Z') {
                        sb.setCharAt(i, (char) (c - 'A' + 'a'));
                    } else if (c >= 'a' && c <= 'z') {
                        sb.setCharAt(i, (char) (c - 'a' + 'A'));
                    }
                }
                sb.reverse();
                substrings.add(sb.toString());
                if (len > maxLength) maxLength = len;
            }
        }
    }
    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int maxSize = 0;
    for (String s : strings) {
        if (s == null) continue;
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                String substring = s.substring(i, j);
                int size = substring.length();
                if (size > maxSize && (isSubstringOfAny(strings, substring) || isSubstringOfAny(strings, new StringBuilder(substring).reverse().toString()))) {
                    maxSize = size;
                }
            }
        }
    }
    return maxSize;
}

private boolean isSubstringOfAny(List<String> strings, String target) {
    for (String s : strings) {
        if (s != null && s.contains(target)) {
            return true;
        }
    }
    return false;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int maxLen = 0;
    for (String str : strings) {
        if (str == null) continue;
        int n = str.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                String substring = str.substring(i, j);
                String inverse = new StringBuilder(substring).reverse().toString();
                boolean found = false;
                for (String s : strings) {
                    if (s == null) continue;
                    if (s.contains(substring) || s.contains(inverse)) {
                        found = true;
                        break;
                    }
                }
                if (found) {
                    maxLen = Math.max(maxLen, j - i);
                }
            }
        }
    }
    return maxLen;
}

