public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    int deposits = 0;
    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                deposits++;
                exploreGrid(grid, visited, i, j, rows, cols);
            }
        }
    }

    return deposits;
}

private static void exploreGrid(char[][] grid, boolean[][] visited, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@' || visited[i][j]) {
        return;
    }

    visited[i][j] = true;

    exploreGrid(grid, visited, i + 1, j, rows, cols);
    exploreGrid(grid, visited, i - 1, j, rows, cols);
    exploreGrid(grid, visited, i, j + 1, rows, cols);
    exploreGrid(grid, visited, i, j - 1, rows, cols);
    exploreGrid(grid, visited, i + 1, j + 1, rows, cols);
    exploreGrid(grid, visited, i + 1, j - 1, rows, cols);
    exploreGrid(grid, visited, i - 1, j + 1, rows, cols);
    exploreGrid(grid, visited, i - 1, j - 1, rows, cols);
}

