public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return null;
    }

    // Convert to uppercase for case-insensitive comparison
    String upperWord1 = word1.toUpperCase();
    String upperWord2 = word2.toUpperCase();

    int len1 = upperWord1.length();
    int len2 = upperWord2.length();
    int sumLengths = len1 + len2;

    if (sumLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Count common letters (frequency-based)
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];

    for (char c : upperWord1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }

    for (char c : upperWord2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        }
    }

    // Count common letters: sum of minimum frequencies
    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(freq1[i], freq2[i]);
    }

    // Build the result
    String result;
    if (common == 0) {
        result = "0";
    } else if (sumLengths % common == 0 && sumLengths / common == 1) {
        result = "1";
    } else {
        int numerator = common;
        int denominator = sumLengths;
        // Reduce the fraction
        int gcd = gcd(numerator, denominator);
        numerator /= gcd;
        denominator /= gcd;

        if (denominator == 1) {
            result = String.valueOf(numerator);
        } else {
            result = numerator + "/" + denominator;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

