    for (int i = 0; i < 26; i++) {
        common += Math.min(freq1[i], freq2[i]);
    }
    int sum = word1.length() + word2.length();
    int gcd = gcd(common, sum);
    String fraction = (common / gcd) + "/" + (sum / gcd);
    if (sum % gcd == 0 && common % gcd == 0) {
        if (sum / gcd == 1) {
            fraction = String.valueOf(common / gcd);
        }
    }
    return "appx(" + word1 + ", " + word2 + ") = " + fraction;
}

