public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Words cannot be null");
    }

    int len1 = word1.length();
    int len2 = word2.length();
    int totalLength = len1 + len2;

    if (totalLength == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Convert to uppercase for case-insensitive comparison
    String upperWord1 = word1.toUpperCase();
    String upperWord2 = word2.toUpperCase();

    int commonCount = 0;

    // Count common letters
    for (int i = 0; i < len1; i++) {
        char c = upperWord1.charAt(i);
        for (int j = 0; j < len2; j++) {
            if (upperWord2.charAt(j) == c) {
                commonCount++;
                break; // Only count once per unique letter in word1
            }
        }
    }

    // Reduce the fraction
    int gcd = gcd(commonCount, totalLength);
    int numerator = commonCount / gcd;
    int denominator = totalLength / gcd;

    String result;
    if (numerator == 0) {
        result = "0";
    } else if (denominator == 1) {
        result = String.valueOf(numerator);
    } else {
        result = numerator + "/" + denominator;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

private static int gcd(int a, int b) {
    a = Math.abs(a);
    b = Math.abs(b);
    if (a == 0) return b;
    if (b == 0) return a;
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

