public boolean canArrange(int[] arr, int k) {
    if (k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int mod = num % k;
        if (mod < 0) {
            mod += k;
        }
        freq[mod]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) {
            if (freq[i] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[i] != freq[j]) {
                return false;
            }
        }
    }
    return true;
}

