public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) {
        return 0;
    }

    // Build adjacency list
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }

    // Memoization to store the minimum edge count needed to visit apples in subtree rooted at node and return to parent
    // We'll use a bottom-up approach (from leaves to root)
    // For each node, if it has an apple or any of its children requires traversal, we add 2 edges for each such child
    // (go down and come back). But if the child subtree has no apples, we don't need to go there.

    // Start DFS from node 0 (root)
    return dfs(0, -1, adj, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int totalEdges = 0;

    for (int neighbor : adj.get(node)) {
        if (neighbor == parent) {
            continue;
        }

        int childEdges = dfs(neighbor, node, adj, hasApple);

        // If the child has an apple or requires visiting its subtree, we need to traverse 2 edges (down and up)
        if (childEdges > 0 || hasApple[neighbor]) {
            totalEdges += 2 + childEdges;
        }
    }

    return totalEdges;
}
