        return false;
    }

    sum /= gcd;
    for (int i = 0; i < n; i++) {
        nums[i] /= gcd;
    }

    // Try all possible subset sizes where average matches
    // For a subset of size k with sum = s, we need s/k = (sum - s)/(n - k)
    // => s*n = sum*k => s = sum*k/n
    // So sum must be divisible by n for integer k

    for (int k = 1; k <= n / 2; k++) {
        if (sum % k == 0) {
            int target = sum / k;
            if (subsetExists(nums, k, target)) {
                return true;
            }
        }
    }

    return false;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return Math.abs(a);
}

private static boolean subsetExists(int[] nums, int k, int target) {
    int n = nums.length;
    // Use bitset DP
    // dp[i] represents the set of sums achievable with a certain number of elements
    // We need to track both count and sum
    // Use a 2D approach or set-based approach

    int maxSum = target;
    // dp[count][sum] = true if we can pick 'count' elements that sum to 'sum'
    boolean[][] dp = new boolean[k + 1][maxSum / 2 + 2]; // sum can't exceed target, but actually we need up to some bound
    // Actually, the maximum sum for k elements is k * max_element, but we only care if sum == target
    // Let's use a set-based approach with bitsets for efficiency

    // Alternative: use a list of sets
    // sets[i] contains all possible sums using exactly i elements
    java.util.Set<Integer>[] sets = new java.util.Set[k + 1];
    for (int i = 0; i <= k; i++) {
        sets[i] = new java.util.HashSet<>();
    }
    sets[0].add(0);

    for (int num : nums) {
        // Update in reverse to avoid using the same element multiple times
        for (int i = k; i >= 1; i--) {
            for (int s : sets[i - 1]) {
                int newSum = s + num;
                if (newSum <= 2 * target / 2 + 100) { // reasonable upper bound
                    sets[i].add(newSum);
                }
            }
        }
    }

    return sets[k].contains(target);
}
