    public boolean hasAllCodes(String s, int k) {
        if (s == null || s.isEmpty() || k <= 0) {
            return false;
        }
        int n = s.length();
        if (n < k) {
            return false;
        }

        // There are 2^k possible binary strings of length k
        int totalNeeded = 1 << k;
        boolean[] seen = new boolean[totalNeeded];

        int current = 0;
        int count = 0;

        // Build the first window
        for (int i = 0; i < k; i++) {
            current = (current << 1) | (s.charAt(i) - '0');
        }
        seen[current] = true;
        count++;

        // Slide the window
        for (int i = k; i < n; i++) {
            // Remove the leftmost bit (it's already shifted out by the next shift)
            // Keep only the last k-1 bits, then add new bit
            int mask = (1 << (k - 1)) - 1;
            current = ((current & mask) << 1) | (s.charAt(i) - '0');

            if (!seen[current]) {
                seen[current] = true;
                count++;
                if (count == totalNeeded) {
                    return true;
                }
            }
        }

        return count == totalNeeded;
    }
