    int current = 0;
    for (int i = 0; i < s.length(); i++) {
        int bit = s.charAt(i) - '0';
        current = ((current << 1) | bit) & (totalCodes - 1);
        if (i >= k - 1) {
            seen.add(current);
            if (seen.size() == totalCodes) {
                return true;
            }
        }
    }
    return seen.size() == totalCodes;
