public int minOperations(int n) {
    // The array arr has arr[i] = 2*i + 1 for 0 <= i < n
    // The sum of the array is n^2 (since sum of first n odd numbers = n^2)
    // The target value to make all elements equal is n (average)
    // We need to count the total amount to move from values less than n to values greater than n
    // 
    // For even n:
    // arr = [1, 3, 5, ..., 2*(n/2)-1, 2*(n/2)+1, ..., 2*n-1]
    // First half: values 1, 3, ..., n-1 (n/2 values, all odd numbers less than n)
    // Second half: values n+1, n+3, ..., 2n-1 (n/2 values, all odd numbers greater than n)
    // 
    // Total operations = sum of (n - arr[i]) for i from 0 to n/2-1
    // = sum of (n - (2*i+1)) for i=0 to n/2-1
    // = sum of (n-1-2*i) for i=0 to n/2-1
    // 
    // Let m = n/2
    // Sum = sum_{i=0}^{m-1} (n-1-2i) = m*(n-1) - 2*(m-1)*m/2 = m*(n-1) - m*(m-1) = m*(n-1-m+1) = m*(n-m)
    // = (n/2) * (n - n/2) = (n/2) * (n/2) = (n/2)^2
    // Wait, let me recalculate:
    // m*(n-1) - m*(m-1) = m*(n-1-m+1) = m*(n-m)
    // For n=6, m=3: 3*(6-3) = 9. Correct!
    // For n=3 (odd case), let's handle separately.

    if (n == 1) {
        return 0;
    }

    if (n % 2 == 0) {
        int m = n / 2;
        return m * m;
    } else {
        // For odd n:
        // arr = [1, 3, 5, ..., n, n+2, n+4, ..., 2n-1]
        // The middle element is exactly n
        // First (n/2) elements: 1, 3, ..., n-2 (n/2 values)
        // Last (n/2) elements: n+2, n+4, ..., 2n-1 (n/2 values)
        // Total operations = sum of (n - arr[i]) for i=0 to n/2-1
        // = sum_{i=0}^{n/2-1} (n - (2i+1)) = sum_{i=0}^{n/2-1} (n-1-2i)
        // Let m = n/2 (integer division, so m = (n-1)/2)
        // Sum = m*(n-1) - 2*(m-1)*m/2 = m*(n-1-m+1) = m*(n-m)
        // For n=3, m=1: 1*(3-1) = 2. Correct!
        // For n=5, m=2: sum = 2*(5-2) = 6
        // Let me verify: arr = [1,3,5,7,9], target = 5
        // Differences: (5-1) + (5-3) + 0 + (7-5) + (9-5) = 4+2+0+2+4 = 12, but we count operations as moving units
        // Actually, each operation moves 1 unit, so total operations = sum of positive differences = (5-1)+(5-3) = 4+2 = 6
        // Yes! So for odd n, m = n/2 (integer division), result = m*(n-m)
        int m = n / 2;
        return m * (n - m);
    }
}
