public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (true) {
        int next = a + b;
        if (next > k) {
            break;
        }
        fibs.add(next);
        a = b;
        b = next;
    }

    // Use greedy approach: repeatedly subtract the largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= remaining) {
            remaining -= fibs.get(i);
            count++;
        }
        if (remaining == 0) {
            break;
        }
    }

    return count;
}
