public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int count = 0;
    int sqrtN = (int) Math.sqrt(n);
    List<Integer> smallFactors = new ArrayList<>();
    List<Integer> largeFactors = new ArrayList<>();

    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            smallFactors.add(i);
            if (i != n / i) {
                largeFactors.add(n / i);
            }
        }
    }

    // Collect all factors: smallFactors in ascending order, then largeFactors in descending order -> reverse to make ascending
    List<Integer> largeFactorsReversed = new ArrayList<>(largeFactors);
    Collections.reverse(largeFactorsReversed);

    List<Integer> allFactors = new ArrayList<>();
    allFactors.addAll(smallFactors);
    allFactors.addAll(largeFactorsReversed);

    if (k > allFactors.size()) {
        return -1;
    }

    return allFactors.get(k - 1);
}

