        return s;
    }

    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (sb.length() > 0) {
            char last = sb.charAt(sb.length() - 1);
            if (isOppositeCaseAndSameLetter(last, c)) {
                sb.deleteCharAt(sb.length() - 1);
                continue;
            }
        }
        sb.append(c);
    }

    return sb.toString();
}

private boolean isOppositeCaseAndSameLetter(char a, char b) {
    if (a == b) return false;
    char lowerA = Character.toLowerCase(a);
    char lowerB = Character.toLowerCase(b);
    if (lowerA != lowerB) return false;

    boolean oneUpper = Character.isUpperCase(a);
    boolean otherUpper = Character.isUpperCase(b);
    return oneUpper != otherUpper;
}
