private int backtrack(String s, int start, java.util.Set<String> seen) {
    if (start == s.length()) {
        return 0;
    }

    int max = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String sub = s.substring(start, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int remaining = backtrack(s, end, seen);
            max = Math.max(max, 1 + remaining);
            seen.remove(sub);
        }
    }
    return max;
}
