private int helper(String s, int start, Set<String> used, int count, int best) {
    int n = s.length();
    // Pruning: even if all remaining characters are unique single chars, total won't exceed best
    if (count + (n - start) <= best) {
        return count >= best ? count : best;
    }
    if (start == n) {
        return count;
    }
    for (int end = start + 1; end <= n; end++) {
        String cur = s.substring(start, end);
        if (!used.contains(cur)) {
            used.add(cur);
            int res = helper(s, end, used, count + 1, best);
            if (res > best) {
                best = res;
            }
            used.remove(cur);
        }
    }
    return best;
}
