public String getSmallestString(int n, int k) {
    // Try to find the largest character we can put at the end such that
    // the remaining n-1 characters can form a valid string with the remaining value.
    // We want the lexicographically smallest string, so we greedily fill from the end.
    String[] result = new String[n];
    for (int i = 0; i < n; i++) {
        result[i] = "";
    }

    for (int i = n - 1; i >= 0; i--) {
        // At position i, we need to choose a character c (1 to 26)
        // After choosing c, we still have i positions to fill, each must be at least 1.
        // The remaining value after choosing c is k - c.
        // The minimum value we can achieve with i positions is i (all 'a').
        // The maximum value we can achieve with i positions is 26 * i (all 'z').
        // So we need: i <= k - c <= 26 * i
        // => k - 26 * i <= c <= k - i
        // Also c must be between 1 and 26.

        int minC = Math.max(1, k - 26 * i);
        int maxC = Math.min(26, k - i);

        // The smallest valid c is minC (since we want lexicographically smallest,
        // and we are filling from right to left, picking the smallest possible at each position
        // from the right ensures the left characters remain as small as possible).
        int c = minC;

        // Convert c to character
        char ch = (char) ('a' + (c - 1));
        result[i] = String.valueOf(ch);
        k = k - c;
    }

    return String.join("", result);
}
