public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    Map<Character, Character> symmetryMap = new HashMap<>();
    symmetryMap.put('0', '0');
    symmetryMap.put('1', '1');
    symmetryMap.put('6', '9');
    symmetryMap.put('8', '8');
    symmetryMap.put('9', '6');

    List<Character> digits = new ArrayList<>();
    for (char c : symmetryMap.keySet()) {
        digits.add(c);
    }

    if (n == 1) {
        for (char c : digits) {
            if (c == '0' || c == '1' || c == '8') {
                result.add(String.valueOf(c));
            }
        }
        return result;
    }

    StringBuilder leftHalf = new StringBuilder();
    char[] halfChars = new char[n / 2];

    void backtrack(int index) {
        if (index == n / 2) {
            StringBuilder current = new StringBuilder(leftHalf.toString());
            StringBuilder rightHalf = new StringBuilder();
            for (int i = current.length() - 1; i >= 0; i--) {
                rightHalf.append(symmetryMap.get(current.charAt(i)));
            }
            String candidate = current.toString() + rightHalf.toString();
            if (n % 2 == 1) {
                char middle = candidate.charAt(n / 2);
                if (middle == '0' || middle == '1' || middle == '8') {
                    result.add(candidate);
                }
            } else {
                result.add(candidate);
            }
            return;
        }

        for (char c : digits) {
            if (index == 0 && n > 1 && c == '0') {
                continue;
            }
            if (n % 2 == 1 && index == n / 2 - 1) {
                if (c != '0' && c != '1' && c != '8') {
                    continue;
                }
            }
            halfChars[index] = c;
            leftHalf.append(c);
            backtrack(index + 1);
            leftHalf.deleteCharAt(leftHalf.length() - 1);
        }
    }

    backtrack(0);
    return result;
}

