            char[] rightArray = new char[rightPart.length];
            for (int i = 0; i < rightPart.length; i++) {
                rightArray[i] = rightPart[rightPart.length - 1 - i];
            }
            sb.append(new String(rightArray));
            if (leftPart.length > 0 && leftPart[0] == '0') {
                // Skip numbers with leading zero for even length
                return;
            }
            result.add(sb.toString());
        }
        return;
    }

    for (char c : pairs.keySet()) {
        leftPart[length - 1] = c;
        rightPart[length - 1] = pairs.get(c);
        generate(length - 1, leftPart, rightPart, pairs, result, isEven);
    }
