public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    List<String> result = new ArrayList<>();
    int firstLen = (n + 1) / 2;
    List<String> combos = new ArrayList<>();
    int totalCombos = Math.pow(4, firstLen - 1);
    if (n % 2 != 0) totalCombos *= 3;
    for (int i = 0; i < totalCombos; i++) {
        combos.add(buildCombo(i, n));
        String revCombo = reverseCombo(combos.get(i), n);
        result.add(combos.get(i) + revCombo);
    }
    return result;
}

private static String buildCombo(int k, int totalLen) {
    int firstLen = (totalLen + 1) / 2;
    int len = firstLen - 1;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < len; i++) {
        sb.append(0);
    }
    int m = 4;
    for (int pos = len - 1; pos >= 0; pos--) {
        int digit = (k / m) % 4;
        char ch;
        switch (digit) {
            case 0: ch = '1'; break;
            case 1: ch = '6'; break;
            case 2: ch = '8'; break;
            default: ch = '9'; break;
        }
        sb.setCharAt(pos, ch);
        m *= 4;
    }
    if (totalLen % 2 != 0) {
        int rem = k % 3;
        char midChar;
        switch (rem) {
            case 0: midChar = '0'; break;
            case 1: midChar = '1'; break;
            default: midChar = '8'; break;
        }
        sb.append(midChar);
    }
    return sb.toString();
}

private static String reverseCombo(String combo, int totalLen) {
    int secondLen = totalLen / 2;
    String leftPart = combo.substring(0, secondLen);
    StringBuilder reversedRight = new StringBuilder();
    for (int i = leftPart.length() - 1; i >= 0; i--) {
        char c = leftPart.charAt(i);
        char mirrored;
        switch (c) {
            case '1': mirrored = '1'; break;
            case '8': mirrored = '8'; break;
            case '6': mirrored = '9'; break;
            default: mirrored = '6'; break;
        }
        reversedRight.append(mirrored);
    }
    return reversedRight.toString();
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {
        {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}
    };

    helper(result, n, 0, "", pairs);

    return result;
}

private static void helper(List<String> result, int n, int depth, String current, char[][] pairs) {
    if (depth == n) {
        result.add(current);
        return;
    }

    // If we are at the middle position for an odd length number
    if (n % 2 == 1 && depth == n - 1) {
        // Only center-symmetric single digits can be placed at the center
        for (int i = 0; i < pairs.length; i++) {
            if (pairs[i][0] == pairs[i][1]) {
                helper(result, n, depth + 1, current + pairs[i][0], pairs);
            }
        }
    } else {
        for (int i = 0; i < pairs.length; i++) {
            // For the first position, don't allow leading zeros (unless n == 1, but that's handled in the center case)
            if (depth == 0 && pairs[i][0] == '0' && n > 1) {
                continue;
            }
            helper(result, n, depth + 1, current + pairs[i][0], pairs);
        }
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    List<String> result = new ArrayList<>();
    int mid = n / 2;
    int halfLen = n / 2;
    int start = (n % 2 == 0) ? 10 : 0;
    int end = (int) Math.pow(10, halfLen + 1);
    String[] leftDigits = {"0", "1", "8", "6", "9"};
    Map<Character, Character> mirrorMap = new HashMap<>();
    mirrorMap.put('0', '0');
    mirrorMap.put('1', '1');
    mirrorMap.put('8', '8');
    mirrorMap.put('6', '9');
    mirrorMap.put('9', '6');
    for (int num = start; num < end; num++) {
        String half = String.format("%0" + halfLen + "d", num);
        String reversed = new StringBuilder(half).reverse().toString();
        StringBuilder center = new StringBuilder(half);
        for (int i = 0; i < mid; i++) {
            char c = reversed.charAt(i);
            center.append(mirrorMap.get(c));
        }
        if (n % 2 == 1) {
            center.append("0");
        }
        result.add(center.toString());
    }
    return result;
}

