    // Check if any two points are the same
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    // Calculate the slopes between the three pairs of points
    // Using cross product to avoid division: (y2-y1)*(x3-x1) == (y3-y1)*(x2-x1) means collinear
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];

    // If the three points are collinear, they do NOT form a boomerang
    long left = (y2 - y1) * (x3 - x1);
    long right = (y3 - y1) * (x2 - x1);

    return left != right;
}
