public static boolean isBoomerang(int[][] points) {
    // A boomerang is defined that formed by three distinct points.
    // In a general interpretation from some problems, it's a set of three points not collinear.
    if (points == null || points.length < 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the points are distinct
    if (x1 == x2 && y1 == y2) return false;
    if (x1 == x3 && y1 == y3) return false;
    if (x2 == x3 && y2 == y3) return false;

    // Calculate cross product to check for collinearity
    // If (x2-x1)(y3-y1) == (y2-y1)(x3-x1) then they are collinear
    long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);

    // If cross product is zero, points are collinear, not a boomerang
    // Otherwise, points form a boomerang (a triangle or non-collinear points)
    return cross != 0;
}
