public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }

    int ax = points[0][0], ay = points[0][1];
    int bx = points[1][0], by = points[1][1];
    int cx = points[2][0], cy = points[2][1];

    // Calculate squared distances
    int ab2 = (ax - bx) * (ax - bx) + (ay - by) * (ay - by);
    int bc2 = (bx - cx) * (bx - cx) + (by - cy) * (by - cy);
    int ac2 = (ax - cx) * (ax - cx) + (ay - cy) * (ay - cy);

    // Check if any two distances are equal
    if (ab2 == bc2 || bc2 == ac2 || ac2 == ab2) {
        return false;
    }

    // Check if points are collinear using cross product
    // (bx - ax) * (cy - ay) == (by - ay) * (cx - ax) means collinear
    if ((bx - ax) * (cy - ay) == (by - ay) * (cx - ax)) {
        return false;
    }

    // If all distances are distinct and points are not collinear, it's a boomerang
    if (ab2 == 0 || bc2 == 0 || ac2 == 0) {
        return false;
    }

    return true;
}
