public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    for (int i = 1; i <= n; i++) {
        result.add(current);
        // Try to go deeper (multiply by 10)
        if (current * 10 <= n) {
            current *= 10;
        } else {
            // Go back up as much as possible
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}
