public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    // Use depth-first search approach to generate lexicographical order
    // Start with 1, and for each number, try to append 0-9 digits
    // BFS/DFS approach: Start with current number, multiply by 10 and add digits
    int current = 1;
    result.add(current);
    for (int i = 1; i < n; i++) {
        // If we can go deeper (current * 10 <= n), do it
        if (current * 10 <= n) {
            current = current * 10;
        } else {
            // If we're at a leaf or can't go deeper, move to next
            while (current % 10 == 9 || current + 1 > n) {
                current = current / 10;
            }
            current = current + 1;
        }
        result.add(current);
    }
    return result;
}
