    if (nums == null || nums.length == 0) {
        return 0;
    }

    Set<Integer> uniqueSet = new HashSet<>();
    Set<Integer> duplicateSet = new HashSet<>();

    for (int num : nums) {
        if (!uniqueSet.contains(num)) {
            uniqueSet.add(num);
        } else {
            duplicateSet.add(num);
        }
    }

    for (int dup : duplicateSet) {
        uniqueSet.remove(dup);
