    for (int i = 1; i <= n; i++) {
        dp[i] = i; // at most i ones
        for (int j = 1; j * j <= i; j++) {
            int remainder = i - j * j;
            if (dp[remainder] + 1 < dp[i]) {
                dp[i] = dp[remainder] + 1;
            }
        }
    }
    return dp[n];
